#!/usr/bin/env python3
import re
import html

# 고품질 번역 사전: page_number -> [번역 블록1, 번역 블록2, ...]
TRANSLATIONS = {
    61: ["전달되는 매개변수 이름(예: userId, approvalStatus, incidentSysId): 커스텀 구성 요소에 접두사를 붙이면 특히 다중 팀 또는 다중 앱 환경에서 명명 충돌을 방지하는 데 도움이 될 수 있습니다. 또한 설명(description) 필드를 활용하여 각 요소의 의도와 기대되는 용도를 설명하면 유지 관리성이 향상되고 신입 개발자의 온보딩에 도움이 됩니다."],
    62: ["다른 곳에 이미 데이터가 존재한다면, 참조(Reference) 필드나 계산된(Calculated) 필드, 또는 파생(Derived) 필드를 사용하여 그곳에서 데이터를 가져오는 것이 합리적일 수 있습니다. 만약 참조된 레코드에 이미 해당 데이터가 있다면, 새로운 커스텀 필드를 만드는 것보다 파생 필드를 사용하는 것이 거의 항상 더 효율적입니다.\n\n커스텀 필드를 생성하는 것이 필요할 때도 있지만, 주의하지 않으면 심각한 성능 저하를 초래할 수 있습니다. 특히 Task 테이블이나 다른 많이 확장된 베이스 테이블에서 작업할 때 더욱 그렇습니다. 따라서 새로운 데이터베이스 컬럼(즉, 필드)을 추가하기 전에 스스로에게 몇 가지 질문을 던져보아야 합니다.\n\n1. 이 필드가 정말 필요한가? 예상되는 데이터가 실제로 가치를 더해주는가?\n2. 더 나은 방법(예: 기존 데이터 활용)이 있는가?\n3. 이 필드가 양식이나 목록에 표시되어야 하는가?\n4. 이 데이터가 이미 다른 곳에 존재하는가?\n\n이 문서의 '코딩하지 말아야 할 때를 알기' 섹션에서 논의하겠지만, 데이터의 출처와 사용처를 파악하는 것이 중요합니다.\n\n필드가 항상 스크립트로 작성된 값이나 계산된 값을 포함해야 한다면, 필드의 딕셔너리 레코드에서 'Calculated' 체크박스를 사용하는 것을 고려해 보세요. 하지만 계산된 필드는 서버 측에서만 실행된다는 점에 유의하세요. 자세한 내용은 '테이블 및 컬럼' 섹션의 '기본값 vs 계산된 값' 부분을 참조하세요.\n\n또한 새 필드를 만든 후에는 이를 기본 양식/목록 보기에 표시할지, 아니면 특정 뷰에만 표시할지 신중하게 결정해야 합니다."],
    63: ["이 필드에 어떤 레이블과 이름을 부여해야 할까요? 전문가 팁: 만약 setAbortAction()을 사용하여 작업을 중단하기로 했다면, 작업의 소스가 실제 로그인된 사용자 세션인지 아니면 API 호출이나 자동화된 비즈니스 로직인지 확인하는 조건을 추가하는 것이 좋습니다. gs.getSession().isInteractive()를 사용하면 됩니다. 이는 사용자의 작업은 차단하면서 백엔드 프로세스의 데이터 저장은 방해하고 싶지 않을 때 매우 유용합니다.\n\n누가 이 필드를 보고 쓸 수 있어야 할까요? 쓰기가 불가능해야 한다면 읽기 전용(Read-only)으로 설정해야 하고, 반드시 입력해야 한다면 필수(Mandatory)로 설정해야 합니다. 단순히 UI 정책으로만 필수를 설정하는 것보다 ACL, 데이터 정책 또는 비즈니스 규칙과 같은 서버 측 구성 요소를 함께 사용하여 서버 측에서도 로직을 강제하는 것이 훨씬 중요합니다.\n\n특정 사용자가 필드나 그 값을 아예 보지 못하게 해야 한다면 반드시 ACL을 사용해야 합니다. 클라이언트 측에서 필드를 숨기는 조치는 숙련된 사용자에 의해 우회될 수 있기 때문입니다.\n\n참조(Reference) 필드(데이터베이스 전문 용어로 '외래 키(Foreign Key) FK 필드')는 ServiceNow 대부분의 테이블에서 핵심적인 구성 요소입니다. 하지만 참조 필드가 매우 큰 테이블을 참조하는 경우, 사용자가 입력할 때 나타나는 '자동 완성' 및 검색 기능이 전체 테이블을 쿼리하기 때문에 매우 오랜 시간이 걸릴 수 있습니다."],
    64: [
        "이에 대한 한 가지 해결책은 참조 필드에서 사용 가능한 옵션 목록을 미리 필터링하는 것입니다. 이는 참조 규정자(Reference Qualifier)를 사용하여 수행할 수 있습니다. 해당 테이블에서 한두 개의 필드만 필요한 경우라면 굳이 테이블을 확장(Extend)할 필요가 없을 수도 있습니다. 반면에 활용도가 높다면 확장하는 것이 좋습니다.",
        "주의할 점: 테이블 B가 테이블 A를 확장하는 경우, 테이블 A를 조회할 때 테이블 B의 레코드도 함께 보게 됩니다. 이는 'OR' 절이 추가되는 것과 같으며, 모든 조건이 충족되어야 합니다.",
        "테이블 A를 볼 때 테이블 A의 모든 하위 레코드가 보이는 이유는, 다른 테이블을 확장하는 테이블들이 일종의 '델타 목록(차이점 목록)'으로 존재하기 때문입니다.",
        "확장 테이블과 피확장 테이블 간의 차이점에 대해서는 '성능 > 쿼리 효율성' 섹션에서 자세히 다룰 예정입니다. 예를 들어 Task [task] 테이블을 직접 조회하면 인시던트(Incident), 변경(Change), 문제(Problem) 레코드 등이 모두 섞여 있는 것을 볼 수 있습니다. 이는 각 테이블이 베이스 Task 테이블을 확장하기 때문입니다. 이러한 참조 필드의 성능은 검색 결과의 수를 제한함으로써 최적화할 수 있으며, 이를 통해 양식에서의 반응성을 훨씬 높일 수 있습니다."
    ],
    65: ["상태(State) 필드의 값과 레이블: 인시던트의 경우 진행 중(In Progress), 대기 중(On Hold), 해결됨(Resolved), 종료됨(Closed), 취소됨(Canceled) 등이 있습니다. 새로운 '비활성(Inactive)' 상태 값을 추가하려면 (예: 중단됨(Abandoned)), 해당 상태의 값을 7보다 크거나 같은 숫자로 설정해야 합니다. 이는 기존 비즈니스 로직이 이 필드의 값에 의존하는 경우가 많기 때문입니다.\n\n마찬가지로 새로운 '활성(Active)' 상태 값을 추가할 때는 티켓의 Active 필드가 true로 유지되어야 하므로 7보다 작은 값을 사용해야 합니다. 양수가 부족하다면 단순히 음수(-1, -2 등)를 사용할 수도 있습니다.\n\n요즘 ServiceNow 'Now' 플랫폼에는 특정 상태 값에 의존하는 하드코딩된 로직이 많지 않지만, 레거시 코드와의 호환성을 위해 값이 7 이상이면 비활성 상태, 7 미만이면 활성 상태로 간주하는 규칙을 따르는 것이 좋습니다."],
    66: ["플랫폼이 상태를 '종료(Closed)'로 판별하는 기준은 State 필드의 딕셔너리 속성에 정의됩니다. OOB 스크립트 도구인 TaskStateUtil은 세미콜론으로 구분된 'close_states' 속성을 사용하여 종료 상태 목록을 관리합니다. 위 스크린샷에서 default_work_state와 close_states 속성을 확인할 수 있습니다.\n\n주의할 점: 선택 옵션의 '값(Value)'과 '순서(Sequence)' 필드를 혼동하지 마세요. Sequence 필드는 드롭다운 목록에서 옵션이 표시되는 순서만 결정합니다.\n\n새로운 테이블을 위한 상태 모델을 만들 때는 이를 추적하기 위한 헬퍼 스크립트 포함(Script Include)을 만드는 것도 고려해 보세요. OOB의 IncidentState 및 IncidentStates 가이드와 비슷하지만 더 단순하게 구현된 다음 예제를 참조하세요."],
    67: [
        "항목을 주문한 사람의 부서 필드는 Users 테이블이며, 특정 ACL이 데이터베이스 뷰(Database View) 보고를 위해 필요하고 생성되어야 합니다. 데이터베이스 뷰는 계산 집약적일 수 있고 항상 최선의 해결책은 아니지만, 때오는 꼭 사용해야 하는 상황이 있습니다.",
        "데이터베이스 뷰 사용 시 몇 가지 추가 지침:\n1. '첫 번째' 또는 '왼쪽' 테이블은 레코드 수가 적은 작은 테이블이어야 합니다. 그래야 데이터베이스 부하가 적습니다.\n2. 데이터베이스 인덱스가 있는 필드에서만 결합(Coalescing)을 수행해야 합니다. 이는 테이블 정의의 관련 목록에서 확인할 수 있습니다.\n3. 테이블 이름과 별칭(Alias)에 SQL 예약어를 사용하지 않도록 하세요. (예약어 목록은 MySQL 공식 문서 등에서 확인할 수 있습니다.)\n4. 기본적으로 관리자가 아닌 사용자는 새로운 데이터베이스 뷰에 접근할 수 없으므로 권한 설정이 필요합니다."
    ],
    68: ["기본값(Default Value) vs 계산된 값(Calculated Value): 이 둘은 매우 다르게 동작하며 목적도 다릅니다. 이 섹션에서는 각각의 용도와 동작 차이를 살펴봅니다.\n\n기본값은 레코드가 삽입될 때, 또는 '새 레코드' 양식이 로드될 때 서버에서 계산됩니다. 이때 current 객체에는 아직 데이터가 없습니다. 필드에 이미 값이 있거나 레코드가 업데이트되는 경우에는 기본값이 적용되지 않습니다. 기본값은 단순한 문자열이나 정수일 수도 있고, 'javascript:' 키워드로 시작하는 복잡한 스크립트일 수도 있습니다.\n\n주의: 기본값 스크립트에서 current 객체를 사용할 순 있지만, 양식이 처음 로드될 때는 값이 비어 있을 수 있습니다. 따라서 스크립트가 실행되더라도 예상치 못한 결과가 나올 수 있음을 염두에 두어야 합니다."],
    69: [
        "나중에 업데이트되거나 값이 변경될 때: 계산된 필드(Calculated Field)는 레코드가 업데이트될 때마다 항상 적용되고 다시 평가됩니다. 계산된 필드 로직을 작성할 때는 성능에 주의해야 합니다.",
        "참고: 계산된 필드는 행(row)을 읽을 때마다 계산됩니다. 즉, 복잡한 처리가 포함된 계산은 매번 다시 실행됩니다. 목록에서 계산된 필드를 표시하지 않더라도 목록의 각 행마다 계산이 수행될 수 있습니다. 종종 '삽입/업데이트 비즈니스 규칙'을 사용하여 필드 값을 설정하는 것이 성능 측면에서 더 나은 결과를 얻을 수 있습니다.\n\n계산된 필드는 레코드가 데이터베이스에서 읽힐 때마다 필드를 업데이트해야 하는 확실한 유즈케이스가 있는 경우에만 사용해야 합니다. 사용자가 양식에서 'null'을 보는 것을 방지하려면, current 객체가 비어 있을 때 표시할 기본 텍스트를 넣거나 아래 스크립트처럼 빈 문자열을 반환하는 것이 좋습니다.\n\n계산된 필드를 활성화하려면 필드 딕셔너리의 고급 보기(Advanced view)에서 'Calculated' 박스를 체크하고 'Calculated Value' 섹션에 스크립트를 작성하세요."
    ],
    70: ["function calculatedFieldValue(current) {\n  var userName, updatedDate;\n  // 레코드가 아직 생성되지 않은 경우 (새 레코드 양식)\n  if (current.sys_created_on.nil()) {\n    return '';\n  }\n  \n  var grUser = new GlideRecord('sys_user');\n  if (grUser.get(gs.getUserID())) {\n    userName = grUser.getDisplayValue();\n    updatedDate = current.getValue('sys_updated_on');\n    return '최종 업데이트: ' + userName + ' (' + updatedDate + ')';\n  }\n  return '';\n}"],
    71: ["양식 레이아웃(FORM LAYOUTS): 양식 레이아웃은 당연해 보일 수 있지만, 시간을 내어 설계를 계획하는 것이 현명합니다. 디자인 지침과 기본 양식 뷰가 준수해야 할 몇 가지 일반적인 규칙은 다음과 같습니다.\n\n가장 일반적인 형태는 데이터를 세 가지 주요 섹션으로 나누는 것입니다.\n1. 상단: '한눈에 파악해야 할' 중요한 세부 정보를 담은 조밀한 2열 섹션. 번호, 담당자, 우선순위 등이 여기에 속합니다.\n2. 중간: 추가 데이터와 다양한 필드들이 포함되는 섹션. 양식이 길어질 경우 여러 섹션으로 나눌 수도 있습니다.\n3. 하단: 전체 목록이나 관련 데이터 등이 배치됩니다.\n\n양식에 3개 이상의 섹션이 있다면 양식 섹션(Form Sections) 기능을 사용하여 그룹화하는 것을 고려하세요. 사용자 설정에 따라 탭으로 표시될 수도 있으므로, 관련 있는 필드들이 같은 섹션에 보이도록 배치하여 사용자가 탭을 앞뒤로 계속 옮겨 다니지 않게 하는 것이 중요합니다."],
    72: ["관련 데이터를 보기 위해 탭을 앞뒤로 계속 옮겨 다니는 것은 좋지 않습니다. 마지막 섹션은 보통 긴 텍스트 문서나 저널 필드(Journal fields)를 위해 할애됩니다. 저널 입력 필드와 저널 목록은 항상 저널 목록 바로 위에 저널 입력 필드를 배치하는 것이 좋습니다. 그렇지 않으면 일반 텍스트 필드로 오해받을 수 있습니다.\n\n완벽할 필요는 없지만, 가급적 대칭적인 양식을 설계하는 것이 좋습니다. 2열 레이아웃을 사용할 때 한쪽 열에만 너무 많은 필드를 몰아넣지 마세요. 다만, 조건에 따라 일부 필드만 표시되는 경우 양식 디자이너에서는 불균형해 보일 수 있지만 실제 사용 환경에서는 적절히 보일 수 있음을 유의하세요.\n\n모든 사용자가 탭 방식의 양식 인터페이스를 사용하는 것은 아닙니다. 따라서 활동 포맷터(Activity formatter)는 보통 관련 목록 바로 직전의 마지막 요소로 배치하는 것이 좋습니다. 그렇지 않으면 일부 사용자는 관련 데이터를 보기 위해 아주 많이 스크롤해야 할 수도 있습니다. 동일한 필드가 한 양식의 다른 위치에 중복되어 나타나지 않도록 주의하세요. 각 필드는 각 뷰에서 단 한 번만 나타나야 합니다."],
    73: [
        "가끔 ServiceNow의 OOB(Out-of-box) 레코드를 수정하거나 교체하고 싶은 유혹을 느끼는 상황이 가끔 발생할 수 있지만, 이를 염두에 두어야 합니다.",
        "OOB 레코드(기본 제공 레코드): 특히 스크립트의 경우, 가급적 OOB 레코드를 수정하지 마세요! 만약 특정 상황에서 스크립트가 실행되지 않게 하고 싶다면, 조건을 추가하여 해당 테이블이나 상황에서는 동작하지 않게 설정하세요. 그런 다음 'Insert and Stay' 기능을 사용하여 레코드를 복제하고, 원하는 조건에서만 실행되도록 구성하세요.\n\n이는 매우 중요합니다. 왜냐하면 각 스크립트 레코드와 인터페이스하거나 이를 트리거하는 수많은 요소들을 모두 파악하기란 극도로 어렵기 때문입니다. OOB 코드를 수정하면 나중에 문제 해결이 매우 어려운 연쇄적인 버그가 발생할 수 있습니다. 또한 인스턴스가 업그레이드되거나 패치될 때, 수정된 OOB 레코드는 업그레이드 프로세스에서 제외되어 최신 기능을 반영하지 못할 수 있습니다."
    ],
    74: ["OOB 스크립트 포함(Script Include) 확장: OOB 스크립트 포함의 경우, 이를 직접 수정하는 대신 확장(Extending) 기능을 사용하여 '재정의'할 수 있습니다. 실제 OOB 스크립트 포함을 수정하지 않으면서도 그 기능을 활용할 수 있는 좋은 방법입니다.\n\n이는 확장하려는 스크립트의 메서드와 속성을 상속받는 새로운 스크립트 포함을 만드는 과정을 포함합니다. 거기에서 새로운 메서드나 속성을 추가하거나, 상속받은 메서드를 재정의할 수 있습니다.\n\n이 작업이 필요한 경우는 다소 드물 수 있지만, 중요한 OOB 스크립트를 직접 수정하지 않고도 기능을 유연하게 변경하거나 재구현할 수 있는 유용한 기술입니다."],
    75: ["재정의하거나 기능을 추가하고 싶다면 다음과 같이 할 수 있습니다. 여기서는 ExampleScriptInclude를 확장하여 ExampleExtendedScriptInclude를 만들었습니다. prototype 객체에 extendsObject(ExampleScriptInclude)를 설정하고, 두 번째 인수로 메서드 객체를 포함하여 특정 메서드를 재정의했습니다.\n\n동일한 이름의 메서드를 작성하면 해당 메서드가 기존 기능을 대체합니다. 또한 상위 클래스에서 사용되는 변수를 재정의하여 동작을 변경할 수도 있습니다. dontOverrideMeBro() 메서드가 ExampleExtendedScriptInclude에 직접 정의되어 있지 않더라도, 상속을 통해 사용 가능합니다. 상속받은 메서드는 재정의된 변수를 사용하여 새로운 메시지를 출력하게 됩니다.\n\n위의 두 스크립트 포함이 인스턴스에 있을 때 다음 코드가 어떻게 출력될지 고려해 보세요."],
    76: ["모범 사례는 특정 기술에 국한된 것이 아니며, 기술 표준과 플랫폼의 기본 아키텍처는 시간이 지나면서 변할 수 있습니다.\n\n전문가 팁: 여전히 확실하지 않다면 팀원이나 아키텍트에게 물어보세요. 저에게 Twitter나 Threads(@TheTimWoodruff)를 통해 언제든지 연락하셔도 좋습니다!\n\n예를 들어 ES3에서 ES5 구문으로의 변화는 JSON 파싱부터 배열과 상호작용하는 방식에 이르기까지 서버 측 스크립트 처리 방식을 크게 바꾸어 놓았습니다. 변화하는 흐름을 놓치지 않는 것이 중요합니다."],
    77: [
        "if (g_form.getValue('state') == 3) { /* 작업 수행 */",
        "실행 경로 테스트(TESTING EXECUTION PATHS): 항상 실행 경로를 테스트하는 것이 중요합니다. 실행 경로란 코드 내의 제어 흐름(control flow)에 따라 코드가 취할 수 있는 논리적 '루트'를 의미합니다. 제어 흐름은 코드가 실행되는 경로를 결정하는 모든 조건문(if/else 등)으로 구성됩니다.\n\n클라이언트 스크립트를 작성한 후에는 상태 필드의 값을 여러 가지로 변경해 보면서 적절한 코드가 오류 없이 실행되는지 테스트해야 합니다. 코드가 한 상황에서는 한 가지 일을 하고, 다른 상황에서는 다른 일을 한다면 각 실행 경로를 모두 테스트하는 것이 현명합니다. 그렇지 않으면 작동하지 않는 코드가 운영 환경에 반영되어 매우 난처한 상황에 처할 수 있습니다."
    ],
    78: ["특정 사례에서는 테스트 사용자가 반드시 당신 자신일 필요는 없습니다. 코드가 올바르게 작동하는 것처럼 보이더라도, 오류를 던지는 코드가 숨어 있을 수 있습니다. 따라서 주의 깊게 관찰하지 않으면 문제를 놓칠 수 있습니다.\n\n테스트를 실행할 때는 브라우저의 콘솔(Console) 창을 열어 오류나 경고가 나타나는지 확인하는 것이 좋습니다. 보통 F12를 눌러 콘솔을 열 수 있습니다. 또한 서버 측 작업을 수행할 때마다 시스템 오류 로그(System Logs > System Log > Errors)를 확인하는 습관을 들이세요.\n\n전문가 팁: '시크릿 모드(Incognito)' 탭을 열어 ServiceNow 인스턴스에 로그인한 뒤, 해당 탭에서 다른 사용자로 위장(Impersonate)하여 테스트하세요. 이렇게 하면 브라우저 세션에 영향을 주지 않으면서 실제 사용자의 시각에서 접근 권한과 레코드를 확인할 수 있습니다.\n\n오류(ERRORS) 처리: 예상치 못한 상황을 처리하기 위해 try{}catch{} 블록을 사용하는 것이 좋습니다. 예를 들어 특정 메서드가 존재할 것이라 확신하더라도, 정의되지 않은(undefined) 예외적인 상황에 대비하여 코드를 try 블록에 넣고 catch 블록에서 오류를 처리하세요."],
    79: ["gs.logError() 또는 범위가 지정된 애플리케이션의 gs.error(): 오류를 직접 처리하는 방식의 장점은 오류가 발생했을 때 수행할 작업을 스스로 결정할 수 있다는 것입니다. 예를 들어 catch 블록에 대체 기능을 넣을 수 있습니다.\n\n하지만 특정 API를 사용하지 못할 수 있음을 이미 알고 있다면, 오류를 포착(catch)하기보다 오류가 발생하지 않도록 미리 방지(prevent)하는 것이 더 바람직합니다. 예를 들어 서비스 포털처럼 특정 API(예: gel())를 사용할 수 없는 환경에서는 'if (typeof gel !== \"undefined\")'와 같은 조건문을 사용하여 코드를 작성하는 것이 좋습니다.\n\n위의 예제 코드는 gel() API를 사용하여 요소에 접근하려 하지만, 이 API는 항상 사용 가능한 것이 아니며 DOM에 직접 접근하기 때문에 가급적 피하는 것이 좋습니다."],
    80: [
        "당신의 로그 메시지를 다른 사람이 본 후, 이를 트리거한 스크립트를 찾을 수 있을까요? 배포 전에 테스트용 디버그/로그 문을 모두 제거했나요?\n\n로그 메시지에 대한 질문: 누군가가 당신이 기록하는 내용을 궁금해할까요? 무언가를 기록할 때는 반드시 그 이유가 있어야 합니다. 단순히 재미로 로그를 남기지 마세요. 불필요한 로그는 인스턴스의 성능 저하를 초래할 수 있습니다.",
        "개발 중에 조건부 블록에 진입하는지 확인하기 위해 로그를 추가하는 것은 괜찮지만, 아래 언급된 대로 운영 환경으로 이동하기 전에는 반드시 제거해야 합니다. 특히 서버 측 API를 사용할 때는 로그 메시지가 민감한 데이터를 포함하고 있는지, 매번 기록될 필요가 있는지 신중히 고려해야 합니다."
    ],
    81: ["이전 코드는 시스템 로그에 경고를 남깁니다. 로그 메시지 자체 뒤의 두 번째 인수는 경고 메시지의 '소스'입니다. 이 경우 해당 로그가 포함된 특정 스크립트 포함(Script Include)과 메서드 이름을 명시하여, 나중에 이 경고를 보는 사람이 문제를 추적하고 해결할 수 있도록 돕습니다.\n\n프로덕션 반영 전 테스트 로그 제거: 대부분의 테스트 로깅에는 gs.log() 대신 gs.debug()를 사용할 것을 권장합니다. gs.debug()를 사용하면 실수로 로그 제거를 잊더라도 디버깅이 활성화되지 않은 프로덕션 환경에서는 로그가 쌓이지 않아 깔끔합니다.\n\n참고: gs.error()와 gs.warn() 메서드는 추가 인수를 문자열 치환(string-replacement)용으로 사용합니다. 예를 들어 gs.warn('티켓 {0}이(가) {1}에게 할당되었습니다.', current.number, current.assigned_to)와 같이 사용할 수 있습니다."],
    82: ["코드 문서화(DOCUMENTATION): 코드를 문서화하는 것은 미래의 자신과 뒤처리를 담당할 다른 개발자를 위해 매우 중요합니다. 코드가 완벽하지 않더라도 잘 문서화되어 있다면 최소한 의도가 무엇이었는지 파악할 수 있으며, 이는 디버깅 프로세스의 기초가 됩니다.\n\n코드를 작성할 때마다 실제 주석(Comments)을 남기는 것뿐만 아니라, '자체 문서화(self-documenting)' 코드를 작성하는 것이 중요합니다. 이 두 가지를 모두 수행해야 합니다! 단순히 '무엇'을 하는지가 아니라, '어떻게' 그리고 '왜' 그렇게 했는지를 설명해야 합니다.\n\n이 장에서는 세 가지 주요 형식을 배웁니다: 변수 이름, 구조와 구문, 그리고 JsDoc이라 불리는 특수 주석입니다. '중국 속담에 이르길, 잉크가 최고의 기억력보다 낫다(Ink is better than the best memory)'는 말이 있습니다."],
    84: ["비록 기술적으로 코드가 더 길어지더라도, 훨씬 명확하게 읽힙니다. 자체 문서화 코드의 한 가지 구조적 팁은 문(statements)을 논리적으로 그룹화하는 것입니다. 예를 들어 변수 초기화를 범위 상단에 모으는 것이 좋습니다.\n\n함수 이름을 정할 때는 명명 규칙을 통해 최대한 많은 정보를 전달하려 노력해야 하지만, 복잡한 로직은 별도의 설명이 필요할 수 있습니다. 이때 JSDoc이 필요합니다. \n\n단순한 로직이라도 시각적으로 구분하여 가독성을 높일 수 있습니다. 예를 들어 변수 선언부와 로직 실행부 사이에 빈 줄을 넣는 것만으로도 코드가 훨씬 깔끔해 보입니다."],
    85: ["updateRecord() 함수 예제: 개발자가 코드를 검색할 때 레코드가 언제 어떻게 업데이트되는지 쉽게 찾을 수 있어야 합니다. \n\n언뜻 보기에 validateRecord() 함수가 유효성 검사뿐만 아니라 업데이트까지 수행한다면 그 이름과 어울리지 않습니다. 유효성 검사 함수는 검사 기능에 집중하고, 업데이트는 별도의 명시적인 함수에서 수행하는 것이 좋습니다.\n\n전문가 팁: JavaScript에서 조건문 뒤에 실행되는 코드가 한 줄뿐이라면 중괄호({})를 생략할 수 있지만, 가급적 중괄호를 포함하는 것을 강력히 추천합니다. 가독성이 좋아질 뿐만 아니라, 나중에 로직을 추가할 때 실수를 줄일 수 있기 때문입니다."],
    86: ["변수 이름을 지을 때 또 다른 좋은 습관은 변수의 단위를 표시하는 것입니다. 예를 들어 단순히 time이라고 하는 대신 timeInSeconds라고 하거나, width 대신 widthPx라고 하면 추가적인 조사 없이도 무슨 일이 일어나고 있는지 훨씬 쉽게 파악할 수 있습니다.\n\n구문(SYNTAX)에 관해서: 다른 프로그래밍 언어와 마찬가지로 JavaScript도 다양한 구문적 트릭을 가지고 있습니다. 그중 몇 가지는 코드를 더 명확하게 만들어 줍니다. 예를 들어 삼항 연산자(Ternary operators [? :])는 단순한 조건부 블록을 한 줄로 표현할 때 매우 유용합니다. 하지만 너무 복잡하게 연결해서 사용하면 오히려 이해하기 어려워질 수 있으니 주의하세요."],
    87: ["효과적인 주석과 이름을 잘 지은 변수를 사용하여 코드를 명확하게 만드세요. 특히 인코딩된 쿼리(encoded query)를 사용할 때 단순히 문자열을 나열하기보다, 각 조건이 무엇을 의미하는지 변수로 정의하여 사용하면 훨씬 읽기 좋습니다.\n\n참고: Sys ID를 하드코딩하는 것은 일반적으로 좋지 않은 생각입니다. 때로는 불가피할 수도 있지만, 프로그래밍 방식으로 레코드를 결정할 수 있다면 그것이 더 좋습니다. 만약 스크립트 곳곳에 특정 사용자의 Sys ID를 하드코딩했는데 그 사람이 퇴사한다면 어떻게 될까요? 이런 경우에는 시스템 속성(System Property)을 사용하는 것이 훨씬 나은 선택입니다. 속성 값 하나만 수정하면 모든 곳에 반영되기 때문입니다."],
    88: [
        "지정하지 않으면 새로운 GlideDateTime 객체가 생성되고 수정된 객체에 대한 참조가 반환됩니다. 즉, 변수가 내부적으로(in-place) 수정된다는 뜻입니다.",
        "/**\n * GlideDateTime 객체를 초기화합니다.\n * @param {GlideDateTime} [gdt] - 초기화에 사용할 객체 (선택)\n */\ninitialize: function(gdt) {\n  if (gdt) {\n    this.gdt = gdt;\n  } else {\n    this.gdt = new GlideDateTime();\n  }\n}\n\n참고: JavaScript의 참조에 의한 전달(pass-by-reference) 방식 때문에, 이 메서드로 변수를 설정하고 클래스의 다른 메서드에서 GDT 객체를 수정하면 원래 변수도 영향을 받게 됨을 유의하세요. JSDoc에 대한 더 자세한 정보는 usejsdoc.org에서 확인할 수 있습니다."
    ],
    89: ["성능은 매우 중요합니다. 이것이 쿼리 효율성, 데이터베이스 테이블 구성, 아니면 기본 레이아웃의 형태이든 상관없이, 사람들이 즐겁게 사용할 수 있는 무언가를 만든다는 것은 '빠른 성능'을 가진 무언가를 만든다는 것을 의미합니다. 애플리케이션이나 솔루션에 성능 향상을 위한 화려한 로직과 쿼리를 추가하고 싶은 유혹이 들겠지만, 모든 비즈니스는 모든 것의 가치가 그 비용의 맥락에서 고려되어야 한다는 점을 알고 있습니다. 페이지 로딩이나 쿼리 완료를 기다리는 데 소요되는 매 시간은 금전적 비용뿐만 아니라 사용자의 분노(ARPH - Average Rage-Per-Hour, 시간당 평균 분노 지수)로 측정되는 심리적 비용을 발생시킵니다. 웹페이지가 로드되기를 기다리는 동안 사용자의 ARPH를 낮게 유지하고 효율성을 높게 유지해야 합니다."],
    90: ["데이터베이스를 효과적으로 사용하기: 쿼리 효율성, 인덱싱 등은 플랫폼의 성능을 결정짓는 핵심 요소입니다. 특히 대량의 데이터를 처리할 때 적절한 인덱스가 없으면 시스템은 전체 테이블을 스캔해야 하므로 성능이 기하급수적으로 저하됩니다. 따라서 자주 조회되는 필드에는 데이터베이스 인덱스를 생성하고, 쿼리가 해당 인덱스를 잘 활용하고 있는지 확인하는 습관을 들여야 합니다."],
}

def clean_html_ko_blocks(page_content):
    """특정 페이지 컨텐츠 내의 모든 lang-ko p 태그 내용을 초기화하거나 정리합니다."""
    # <div class="lang-ko">...</div> 블록들을 찾아서 내부의 p 태그들을 하나로 합치거나 정리할 수 있습니다.
    # 하지만 여기서는 단순히 정규표현식으로 각 블록을 찾아서 순서대로 교체하는 방식을 선택합니다.
    pass

def apply_translations(input_file, output_file):
    with open(input_file, 'r', encoding='utf-8') as f:
        content = f.read()
    
    for page_num, translations in TRANSLATIONS.items():
        # 페이지 섹션 추출
        page_pattern = r'(<section class="page" id="page-' + str(page_num) + r'">)(.*?)(</section>)'
        page_match = re.search(page_pattern, content, flags=re.DOTALL)
        
        if not page_match:
            continue
            
        header = page_match.group(1)
        page_body = page_match.group(2)
        footer = page_match.group(3)
        
        # lang-ko 블록들을 하나씩 찾아서 교체
        # 겹침 방지를 위해 finditer 사용 및 새로운 바디 생성
        ko_blocks = list(re.finditer(r'(<div class="lang-ko">.*?<div class="lang-tag ko">KO</div>\s*)(.*?)\s*(</div>)', page_body, flags=re.DOTALL))
        
        if len(ko_blocks) == 0:
            continue
            
        if len(ko_blocks) != len(translations):
            print(f"Warning: Page {page_num} has {len(ko_blocks)} blocks, but {len(translations)} translations. Skipping precise replacement.")
            continue
            
        new_page_body = ""
        last_end = 0
        for i, match in enumerate(ko_blocks):
            new_page_body += page_body[last_end:match.start()]
            
            # 번역 텍스트 처리
            raw_text = translations[i]
            safe_text = raw_text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
            # 단락 및 줄바꿈
            formatted_text = "<p>" + safe_text.replace('\n\n', '</p>\n<p>').replace('\n', '<br>\n') + "</p>"
            
            # 블록 재구성
            new_block = match.group(1) + formatted_text + "\n                    " + match.group(3)
            new_page_body += new_block
            last_end = match.end()
            
        new_page_body += page_body[last_end:]
        
        # 전체 컨텐츠에서 페이지 섹션 교체
        content = content[:page_match.start()] + header + new_page_body + footer + content[page_match.end():]

    with open(output_file, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f"Apply translations completed (Batch 3 - Final): {output_file}")

if __name__ == '__main__':
    apply_translations(r'F:\projects\Video_to_Text\ServiceNow_Handbook_Bilingual.html', r'F:\projects\Video_to_Text\ServiceNow_Handbook_Bilingual.html')
